import flowio, numpy as np
from sklearn.cluster import KMeans

FL = ['V450-A','V525-A','B530-A','B710-A','YG586-A','YG780-A','R670-A','R780-A']
IDX = {c: 3+i for i,c in enumerate(FL)}
FSC_A, FSC_H, SSC_A = 0, 1, 2

def load(path):
    fd = flowio.FlowData(path)
    return np.array(fd.events, dtype=float).reshape(-1, fd.channel_count)

def split_pos_neg(col):
    x = np.log10(np.clip(col, 1.0, None)).reshape(-1,1)
    km = KMeans(n_clusters=2, n_init=10, random_state=0).fit(x)
    means = km.cluster_centers_.ravel()
    hi = int(np.argmax(means))
    return (km.labels_ == hi)

def control_spill(path, det, bg_med):
    ev = load(path)
    posmask = split_pos_neg(ev[:, IDX[det]])
    pos = ev[posmask]
    row = {}
    denom = np.median(pos[:, IDX[det]]) - bg_med[det]
    for d in FL:
        row[d] = (np.median(pos[:, IDX[d]]) - bg_med[d]) / denom
    return row, int(posmask.sum())

def unstained_bg(path):
    ev = load(path)
    return {d: float(np.median(ev[:, IDX[d]])) for d in FL}
EOF
