bg_cells = unstained_bg('/task/input/fcs/ctrl_unstained.fcs')
print('bg cell medians:', {k: round(v,1) for k,v in bg_cells.items()})

specs_A = [
    ('BV421','V450-A','/task/input/fcs/ctrl_BV421.fcs','beads'),
    ('Zombie Aqua','V525-A','/task/input/fcs/ctrl_ZombieAqua.fcs','cells'),
    ('FITC','B530-A','/task/input/fcs/ctrl_FITC.fcs','beads'),
    ('PerCP-Cy5.5','B710-A','/task/input/fcs/ctrl_PerCPCy55_cells.fcs','cells'),
    ('PE','YG586-A','/task/input/fcs/ctrl_PE.fcs','beads'),
    ('PE-Cy7','YG780-A','/task/input/fcs/ctrl_PECy7.fcs','beads'),
    ('APC','R670-A','/task/input/fcs/ctrl_APC.fcs','beads'),
    ('APC-Cy7','R780-A','/task/input/fcs/ctrl_APCCy7.fcs','beads'),
]

def build(specs):
    S = np.zeros((8,8)); counts={}
    for f,(name,det,path,carrier) in zip(range(8), specs):
        ev = load(path)
        posmask = split_pos_neg(ev[:, IDX[det]])
        pos = ev[posmask]
        if carrier == 'beads':
            neg = ev[~posmask]
            bg = {d: float(np.median(neg[:, IDX[d]])) for d in FL}
        else:
            bg = bg_cells
        counts[name] = int(posmask.sum())
        denom = np.median(pos[:, IDX[det]]) - bg[det]
        for j,d in enumerate(FL):
            S[f, j] = (np.median(pos[:, IDX[d]]) - bg[d]) / denom
    return S, counts

for grp, specs in [('A (641V)', specs_A), ('B (703V)', [s if s[0]!='PE-Cy7' else ('PE-Cy7','YG780-A','/task/input/fcs/ctrl_PECy7_rerun.fcs','beads') for s in specs_A])]:
    S, counts = build(specs)
    print('\nGroup', grp, 'pos counts:', counts)
    print('S matrix (rows=fluoro in panel order, cols=detectors):')
    print(np.array2string(S, precision=4, suppress_small=True))
    print('det(S)=', np.linalg.det(S))
